import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { of, Observable } from 'rxjs';

export interface NotificationItem {
    id: number;
    title: string;
    timestamp: string;
}

export interface NotificationResponse {
    data: NotificationItem[];
}

@Injectable({
    providedIn: 'root',
})
export class WhatNewService {
    private mockDataPath = 'assets/mock-notifications.json';
    private notifications: NotificationItem[] = [];

    constructor(private http: HttpClient) {}

    getListWhatNew(): Observable<NotificationResponse> {
        return this.http.get<NotificationResponse>(this.mockDataPath);
    }

    getDetailWhatNew(id: string): Observable<{ data: NotificationItem }> {
        const item = this.notifications.find(n => n.id === +id) || null;
        if (item) {
            return of({ data: item });
        }
        return of({ data: {} as NotificationItem });
    }

    setNotifications(notifications: NotificationItem[]): void {
        this.notifications = notifications;
    }
}
