import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { API_URL } from './../common';

const BASE_URL = `${API_URL}/api/ICD10/`;
const BASE_URL_TT06 = `${API_URL}/api/ICD10_TT06/`;
const BASE_URL_ICD9 = `${API_URL}/api/ICD9/`;
const YHCT_BASE = `${API_URL}/api/YHCT/`;

/**
 * Search APIs with html=true return status 'failure' and a plain
 * "Không tìm thấy kết quả thích hợp!" message (no result links) when nothing matches.
 */
export function hasSearchHtmlResults(data: any): boolean {
    return !!data?.html && /<a\s[^>]*href=/i.test(data.html);
}

@Injectable({
    providedIn: 'root',
})
export class SearchService {
    private apiUrl = 'https://api.ipify.org?format=json';
    public client_ip: string;
    constructor(private httpClient: HttpClient) {
        this.getIpAddress().subscribe(
            (data: any) => {
                this.client_ip = data.ip;
            },
            (error) => {
                console.log('Error:', error);
            }
        );
    }
    getIpAddress(): Observable<any> {
        return this.httpClient.get<any>(this.apiUrl);
    }

    search(q: any | undefined, lang: string, vol1: boolean, vol3: boolean) {
        if (!q || q === '*') {
            q = '';
        } else {
            q = q.toLowerCase();
        }
        let headers = new HttpHeaders({});
        if (this.client_ip) {
            headers = headers.set('X-Client-IP', this.client_ip);
        }
        return this.httpClient.get<any>(`${BASE_URL}search/${q}?lang=${lang}&vol1=${vol1 ? 1 : 0}&vol3=${vol3 ? 1 : 0}&html=true`, {
            headers: headers,
        });
    }

    getListTreeOfSearch(model: string, id: string | number, lang: string) {
        return this.httpClient.get<any>(`${BASE_URL}tree/${model}?id=${id}&lang=${lang}`);
    }

    search_TT06(q: any | undefined, lang: string, vol1: boolean, vol3: boolean) {
        if (!q || q === '*') {
            q = '';
        } else {
            q = q.toLowerCase();
        }
        let headers = new HttpHeaders({});
        if (this.client_ip) {
            headers = headers.set('X-Client-IP', this.client_ip);
        }
        return this.httpClient.get<any>(`${BASE_URL_TT06}search/${q}?lang=${lang}&vol1=${vol1 ? 1 : 0}&vol3=${vol3 ? 1 : 0}&html=true`, {
            headers: headers,
        });
    }

    getListTreeOfSearch_TT06(model: string, id: string | number, lang: string) {
        return this.httpClient.get<any>(`${BASE_URL_TT06}tree/${model}?id=${id}&lang=${lang}`);
    }

    search_ICD9(q: any | undefined, lang: string) {
        let headers = new HttpHeaders({});
        if (this.client_ip) {
            headers = headers.set('X-Client-IP', this.client_ip);
        }
        if (!q || q === '*') {
            q = '';
        } else {
            q = q.toLowerCase();
        }
        return this.httpClient.get<any>(`${BASE_URL_ICD9}search/${q}?lang=${lang}&html=true`, {
            headers: headers,
        });
    }

    getListTreeOfSearch_ICD9(model: string, id: number, lang: string) {
        return this.httpClient.get<any>(`${BASE_URL_ICD9}tree/${model}?id=${id}&lang=${lang}`);
    }

    search_YHCT(q: any | undefined, version: string) {
        let headers = new HttpHeaders({});
        if (this.client_ip) {
            headers = headers.set('X-Client-IP', this.client_ip);
        }
        if (!q || q === '*') {
            q = '';
        } else {
            q = q.toLowerCase();
        }
        return this.httpClient.get<any>(`${YHCT_BASE}search/${q}?version=${version}&html=true`, {
            headers: headers,
        });
    }

    getListTreeOfSearch_YHCT(model: string, id: number, version: string) {
        return this.httpClient.get<any>(`${YHCT_BASE}tree/${model}?id=${id}&version=${version}`);
    }
}
