import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { ToastrService } from 'ngx-toastr';

@Component({
  selector: 'app-external-site',
  templateUrl: './external-site.component.html'
})
export class ExternalSiteComponent implements OnInit {
  siteUrl: SafeResourceUrl = '';
  siteName: string = '';
  isLoading: boolean = true;
  hasError: boolean = false;

  constructor(
    private route: ActivatedRoute,
    private sanitizer: DomSanitizer,
    private toastService: ToastrService
  ) {}

  ngOnInit(): void {
    this.route.data.subscribe(data => {
      let url = data['url'] || '';
      if (data['supportLang']) {
        const storedLang = localStorage.getItem('lang');
        const pageLang = (storedLang || document?.documentElement?.lang || navigator.language || 'en').toLowerCase();
        const lang = pageLang.startsWith('vi') ? 'vi' : 'en';
        const separator = url.includes('?') ? '&' : '?';
        url = `${url}${separator}lang=${lang}`;
      }
      this.siteUrl = this.sanitizer.bypassSecurityTrustResourceUrl(url);
      this.siteName = data['title'] || 'External Site';
    });
  }

  onIframeLoad(): void {
    this.isLoading = false;
  }

  onIframeError(): void {
    this.isLoading = false;
    this.hasError = true;
    this.toastService.error('Không thể tải trang. Vui lòng thử lại.', 'Lỗi tải trang');
  }
}
