import { Component, Input, Output, EventEmitter, OnInit, OnChanges, OnDestroy, SimpleChanges, ViewChild, ElementRef, AfterViewChecked } from '@angular/core';
import { ChatbotService, ChatSession, ChatMessage, IcdCodeInfo, MessageFeedback } from '../../../shared/services/chatbot.service';
import { SenseSphereOAuthService, SenseSphereUserInfo, SenseSphereSystemInfo, SenseSphereBotInfo } from '../../../shared/services/sensesphere-oauth.service';
import { Subject, firstValueFrom } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { ToastrService } from 'ngx-toastr';
import { environment } from '../../../environments/environment';

export type ChatbotMode = 'sidebar' | 'floating';

@Component({
    selector: 'app-chatbot-panel',
    templateUrl: './chatbot-panel.component.html',
    styleUrls: ['chatbot-panel.component.scss'],
    host: {
        '[tabindex]': '"-1"',
        '[style.outline]': '"none"'
    },
})
export class ChatbotPanelComponent implements OnInit, OnChanges, OnDestroy, AfterViewChecked {
    @Input() mode: ChatbotMode = 'floating';
    @Input() visible = true;
    @Input() botUuid = '';
    @Input() botType = 'ICD-10';
    @Output() close = new EventEmitter<void>();
    @Output() navigateToCode = new EventEmitter<IcdCodeInfo>();

    @ViewChild('messagesContainer') private messagesContainer!: ElementRef;

    messages: ChatMessage[] = [];
    currentMessage = '';
    isLoading = false;
    session: ChatSession | null = null;

    // Loading overlay state
    isLoadingOverlay = false;
    loadingText = 'Đang khởi tạo...';

    // Toast notification state
    toastMessage = '';
    private toastTimeout: number | null = null;

    systemInfo: SenseSphereSystemInfo | null = null;
    botInfo: SenseSphereBotInfo | null = null;

    // Feedback modal state
    showFeedbackModal = false;
    selectedRating = 0;
    feedbackComment = '';
    currentFeedbackMsg: ChatMessage | null = null;

    // Confirm redirect state
    showConfirmRedirect = false;

    // Image lightbox state
    showLightboxImg = false;
    lightboxImageUrl = '';

    // Usage stats
    bonusMessagesRemaining = 0;

    private destroy$ = new Subject<void>();
    private shouldScrollToBottom = true;
    // Set once initChat() has loaded the session for the current bot
    private sessionReady = false;

    constructor(
        private chatbotService: ChatbotService,
        private oauthService: SenseSphereOAuthService,
        private toastService: ToastrService
    ) {}

    get isAuthenticated(): boolean {
        return this.oauthService.isAuthenticated();
    }

    get userId(): string | null {
        return this.oauthService.getUserId();
    }

    get userInfo(): SenseSphereUserInfo | null {
        return this.oauthService.getUserInfo();
    }

    getUserAvatar(): string | null {
        return this.userInfo?.avatar || null;
    }

    getBotAvatar(): string | null {
        return this.botInfo?.avatar || null;
    }

    getBotName(): string {
        return this.botInfo?.name || this.botType;
    }

    getBotDescription(): string {
        return this.botInfo?.description || '';
    }

    get isMaintenanceMode(): boolean {
        return environment.chatbot?.enabled === false;
    }

    getFullChatUrl(): string | null {
        if (!this.botUuid) return null;
        let url = `https://sensesphere.ai/chat/?theme=light&uuid=${this.botUuid}`;
        if (this.session?.session_uuid) {
            url += `&session=${this.session.session_uuid}`;
        }
        return url;
    }

    private ensureUserInfoLoaded(): void {
        if (this.oauthService.isAuthenticated() && !this.oauthService.getUserInfo()) {
            const token = this.oauthService.getToken();
            const userId = this.oauthService.getUserId();
            
            if (token && userId) {
                this.oauthService.fetchUserInfo(token, userId).catch(() => {
                    console.warn('Failed to fetch user info on init');
                });
            }
        }
    }

    onLogin(): void {
        this.oauthService.login();
    }

    onLogout(): void {
        if (confirm('Bạn có muốn đăng xuất?')) {
            this.oauthService.logout();
            this.chatbotService.clearSession();
            this.messages = [];
            this.session = null;
        }
    }

    ngOnInit(): void {
        // Subscribe to session updates once
        this.chatbotService.session$
            .pipe(takeUntil(this.destroy$))
            .subscribe((session: ChatSession | null) => {
                this.session = session;
                if (session) {
                    this.messages = session.messages;
                } else {
                    // Clear messages when session is null (e.g., during bot switch)
                    this.messages = [];
                }
                this.shouldScrollToBottom = true;
            });

        // Pick up questions forwarded from manual search
        this.chatbotService.pendingQuestion$
            .pipe(takeUntil(this.destroy$))
            .subscribe(() => this.sendPendingQuestion());

        this.setBotUuidAndInit();
        this.ensureUserInfoLoaded();
        this.loadSystemInfo();
        this.loadBotInfo();
    }

    private loadBotInfo(): void {
        if (this.botUuid) {
            this.oauthService.fetchBotInfo(this.botUuid).then(info => {
                if (info) {
                    this.botInfo = info;
                }
            });
        }
    }

    private loadSystemInfo(): void {
        this.oauthService.fetchSystemInfo().then(info => {
            if (info) {
                this.systemInfo = info;
            }
        });
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['botUuid'] && !changes['botUuid'].firstChange) {
            this.setBotUuidAndInit();
        }
    }

    private setBotUuidAndInit(): void {
        // Clear local state before switching to new bot
        this.messages = [];
        this.session = null;
        this.sessionReady = false;

        if (!this.botUuid) {
            return;
        }
        // Set botUuid on the service before initializing
        this.chatbotService.botUuid = this.botUuid;

        // Initialize session (subscription is already set up in ngOnInit)
        this.initChat();
    }

    ngAfterViewChecked(): void {
        if (this.shouldScrollToBottom) {
            this.scrollToBottom();
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next();
        this.destroy$.complete();
        if (this.toastTimeout) {
            clearTimeout(this.toastTimeout);
        }
    }

    private initChat(): void {
        this.showLoadingOverlay('Đang khởi tạo...');

        const sessionRequest$ = this.chatbotService.hasSession()
            ? this.chatbotService.resumeSession()
            : this.chatbotService.initSession();

        sessionRequest$.subscribe({
            next: () => {
                this.hideLoadingOverlay();
                this.isLoading = false;
                this.sessionReady = true;
                this.sendPendingQuestion();
            },
            error: (error) => {
                this.hideLoadingOverlay();
                this.isLoading = false;
                if (error?.status === 401 || error?.status === 403) {
                    this.toastService.error('Phiên làm việc không hợp lệ. Vui lòng đăng nhập lại để tiếp tục.', 'Lỗi phiên');
                } else {
                    const errorMsg = error?.error?.message || error?.error?.error || error?.message || 'Không thể khởi tạo phiên chat. Vui lòng thử lại.';
                    this.toastService.error(errorMsg, 'Lỗi');
                }
            },
        });
    }

    private sendPendingQuestion(): void {
        // Wait until the session is ready and no message is in flight
        if (!this.sessionReady || this.isLoading || this.isMaintenanceMode) {
            return;
        }
        const question = this.chatbotService.consumePendingQuestion(this.botUuid);
        if (question) {
            // Send the forwarded question without discarding what the user is typing
            const draft = this.currentMessage;
            this.currentMessage = question;
            this.onSend();
            this.currentMessage = draft;
        }
    }

    private showLoadingOverlay(text: string): void {
        this.loadingText = text;
        this.isLoadingOverlay = true;
    }

    private hideLoadingOverlay(): void {
        this.isLoadingOverlay = false;
        this.loadingText = '';
    }

    showToast(message: string, duration = 2000): void {
        if (this.toastTimeout) {
            clearTimeout(this.toastTimeout);
        }
        this.toastMessage = message;
        this.toastTimeout = setTimeout(() => {
            this.toastMessage = '';
        }, duration) as unknown as number;
    }

    onSend(): void {
        if (this.isMaintenanceMode) {
            this.toastService.info('Tính năng chatbot tích hợp đang bảo trì. Truy cập trang chủ Chatbot để sử dụng đầy đủ tính năng.', 'Thông báo');
            return;
        }
        if (!this.currentMessage.trim() || this.isLoading) {
            return;
        }

        const message = this.currentMessage.trim();
        this.currentMessage = '';
        this.isLoading = true;

        // Check if session exists, if not create one
        const currentSession = this.chatbotService.getCurrentSession();
        if (!currentSession) {
            const sessionRequest$ = this.chatbotService.hasSession()
                ? this.chatbotService.resumeSession()
                : this.chatbotService.initSession();

            sessionRequest$.subscribe({
                next: () => this.sendUserMessage(message),
                error: (error) => {
                    this.isLoading = false;
                    if (error?.status === 401 || error?.status === 403) {
                        this.toastService.error('Phiên làm việc không hợp lệ. Vui lòng đăng nhập lại để tiếp tục chat.', 'Lỗi phiên');
                    } else {
                        const errorMsg = error?.error?.message || error?.error?.error || error?.message || 'Không thể khởi tạo phiên chat. Vui lòng thử lại.';
                        this.toastService.error(errorMsg, 'Lỗi');
                    }
                }
            });
        } else {
            this.sendUserMessage(message);
        }
    }

    private sendUserMessage(message: string): void {
        // Add user message locally
        this.chatbotService.addUserMessage(message);
        this.shouldScrollToBottom = true;

        // Send to bot
        this.chatbotService.sendMessage(message).subscribe({
            next: () => {
                this.isLoading = false;
                this.shouldScrollToBottom = true;
                this.sendPendingQuestion();
            },
            error: (error) => {
                this.isLoading = false;
                if (error?.status === 401 || error?.status === 403) {
                    this.toastService.error('Phiên làm việc không hợp lệ. Vui lòng đăng nhập lại để tiếp tục chat.', 'Lỗi phiên');
                } else {
                    const errorMsg = error?.error?.message || error?.error?.error || error?.message || 'Không thể gửi tin nhắn. Vui lòng thử lại.';
                    this.toastService.error(errorMsg, 'Lỗi');
                }
            },
        });
    }

    onKeyPress(event: KeyboardEvent): void {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            this.onSend();
        }
    }

    onCopyMessage(message: string): void {
        navigator.clipboard.writeText(message).then(() => {
            this.showToast('Đã sao chép vào bộ nhớ tạm');
        }).catch(() => {
            this.showToast('Không thể sao chép');
        });
    }

    onCodeClick(path: string): void {
        const normalizedPath = (path || '').trim();
        if (!normalizedPath) {
            return;
        }

        const safePath = normalizedPath.replace(/&amp;/g, '&');
        let parsedUrl: URL | null = null;

        try {
            parsedUrl = /^https?:\/\//i.test(safePath)
                ? new URL(safePath)
                : new URL(safePath, 'https://icd.kcb.vn');
        } catch {
            // Ignore invalid URL values from bot content.
            return;
        }

        const model = parsedUrl.searchParams.get('model');
        const id = parsedUrl.searchParams.get('id');

        if (model && id) {
            const normalizedPath = parsedUrl.pathname + parsedUrl.search;
            this.navigateToCode.emit({ path: normalizedPath, model: model, id: id });
            return;
        }

        if (/^https?:\/\//i.test(safePath)) {
            window.open(safePath, '_blank', 'noopener,noreferrer');
        }
    }

    closeChat(): void {
        this.close.emit();
    }

    newChat(): void {
        if (confirm('Bạn có muốn bắt đầu cuộc trò chuyện mới?')) {
            this.showLoadingOverlay('Đang tạo cuộc trò chuyện mới...');
            this.chatbotService.createNewSession().subscribe({
                next: (session) => {
                    this.messages = session.messages;
                    this.hideLoadingOverlay();
                    this.shouldScrollToBottom = true;
                },
                error: (error) => {
                    this.hideLoadingOverlay();
                    this.isLoading = false;
                    if (error?.status === 401 || error?.status === 403) {
                        this.toastService.error('Phiên làm việc không hợp lệ. Vui lòng đăng nhập lại để tiếp tục.', 'Lỗi phiên');
                    } else {
                        const errorMsg = error?.error?.message || error?.error?.error || error?.message || 'Không thể tạo cuộc trò chuyện mới. Vui lòng thử lại.';
                        this.toastService.error(errorMsg, 'Lỗi');
                    }
                }
            });
        }
    }

    private scrollToBottom(): void {
        if (this.messagesContainer) {
            const element = this.messagesContainer.nativeElement;
            element.scrollTop = element.scrollHeight;
        }
        this.shouldScrollToBottom = false;
    }

    onFeedback(event: { type: 'suggest' | 'rate', rating?: number }, msg: ChatMessage): void {
        if (event.type === 'rate') {
            this.submitQuickRating(msg, event.rating || 5);
        } else if (event.type === 'suggest') {
            this.showConfirmRedirect = true;
        }
    }

    confirmRedirect(): void {
        const url = this.getFullChatUrl();
        if (url) {
            window.open(url, '_blank', 'noopener noreferrer');
        }
        this.showConfirmRedirect = false;
    }

    cancelRedirect(): void {
        this.showConfirmRedirect = false;
    }

    setRating(rating: number): void {
        this.selectedRating = rating;
    }

    async submitFeedback(): Promise<void> {
        if (!this.currentFeedbackMsg || !this.session?.session_id) return;

        try {
            const result = await firstValueFrom(
                this.chatbotService.rateMessage(this.session!.session_id, this.currentFeedbackMsg.id, this.selectedRating)
            );

            if (result.success) {
                this.updateLocalFeedback(this.currentFeedbackMsg, {
                    rating: this.selectedRating,
                    liked: true,
                    submitted_at: new Date().toISOString()
                });

                if (result.bonus_messages_earned > 0) {
                    this.showToast(`Chúc mừng! Bạn nhận được +${result.bonus_messages_earned} tin thưởng!`, 4000);
                    await this.loadUsageStats();
                } else {
                    const stars = '★'.repeat(this.selectedRating);
                    this.showToast(`Cảm ơn bạn đã đánh giá! ${stars}`, 3000);
                }
            }
        } catch (error: any) {
            console.error('Feedback error:', error);
            if (error?.status === 401) {
                this.showToast('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.', 5000);
            } else if (error?.status === 403) {
                this.showToast('Phiên chat này không thuộc về bạn. Vui lòng tạo cuộc trò chuyện mới sau khi đăng nhập.', 5000);
            } else {
                this.showToast('Không thể gửi đánh giá. Vui lòng thử lại.', 3000);
            }
        }

        this.closeFeedbackModal();
    }

    async submitQuickRating(msg: ChatMessage, rating: number): Promise<void> {
        if (!msg || !this.session?.session_id) return;

        try {
            const result = await firstValueFrom(
                this.chatbotService.rateMessage(this.session!.session_id, msg.id, rating)
            );

            this.updateLocalFeedback(msg, {
                rating: rating,
                liked: true,
                submitted_at: new Date().toISOString()
            });

            if (result?.bonus_messages_earned > 0) {
                this.showToast(`Chúc mừng! Bạn nhận được +${result.bonus_messages_earned} tin thưởng!`, 4000);
                await this.loadUsageStats();
            } else {
                const stars = '★'.repeat(rating);
                this.showToast('Cảm ơn bạn đã đánh giá tích cực!', 3000);
            }
        } catch (error: any) {
            console.error('Quick rating error:', error);
            if (error?.status === 401) {
                this.showToast('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.', 5000);
            } else if (error?.status === 403) {
                this.showToast('Phiên chat này không thuộc về bạn. Vui lòng tạo cuộc trò chuyện mới sau khi đăng nhập.', 5000);
            } else {
                this.showToast('Không thể gửi đánh giá. Vui lòng thử lại.', 3000);
            }
        }
    }

    async loadUsageStats(): Promise<void> {
        try {
            const stats = await firstValueFrom(this.chatbotService.getUsageStats());
            if (stats) {
                this.bonusMessagesRemaining = stats.bonus_messages_remaining || 0;
            }
        } catch {
            // Graceful fallback - usage stats are optional
        }
    }

    onSuggestion(text: string): void {
        this.currentMessage = text;
        this.onSend();
    }

    showLightbox(url: string): void {
        this.lightboxImageUrl = url;
        this.showLightboxImg = true;
    }

    closeLightbox(): void {
        this.showLightboxImg = false;
        this.lightboxImageUrl = '';
    }

    closeFeedbackModal(): void {
        this.showFeedbackModal = false;
    }

    onKeyDown(event: KeyboardEvent): void {
        if (event.key === 'Escape') {
            if (this.showLightboxImg) {
                this.closeLightbox();
            } else if (this.showFeedbackModal) {
                this.closeFeedbackModal();
            } else if (this.showConfirmRedirect) {
                this.cancelRedirect();
            }
        }
    }

    private updateLocalFeedback(msg: ChatMessage, feedback: MessageFeedback): void {
        if (!this.session) return;

        this.chatbotService.updateMessageFeedback(this.session.session_id, msg.id, feedback);
    }

    getWelcomeMessage(): string {
        const botName = this.getBotName();
        return `Xin chào! Tôi là ${botName}. Tôi có thể giúp bạn tìm hiểu về các mã ${this.botType}. Hãy hỏi tôi bất kỳ câu hỏi nào!`;
    }
}
