import { Component, Input } from '@angular/core';
import { IcdService } from 'src/shared/services/icd.service';
import { ToastrService } from 'ngx-toastr';
import { FeedbackModalData, FeedbackModalConfig } from './feedback-modal.models';

// bootstrap
declare var bootstrap: any;

@Component({
    selector: 'app-feedback-modal',
    templateUrl: './feedback-modal.component.html',
    styleUrls: ['./feedback-modal.component.scss']
})
export class FeedbackModalComponent {
    @Input() config: FeedbackModalConfig = {};

    private modal: any;
    private currentData: FeedbackModalData | null = null;

    // Form data
    feedback = '';
    senderName = '';
    senderEmail = '';

    constructor(
        private icdService: IcdService,
        private toastService: ToastrService
    ) {}

    /**
     * Opens the modal by extracting data from a DOM element
     * The element is expected to have sibling elements with classes:
     * - content: contains the HTML content
     * - content-raw: contains the raw text content
     * - field: contains the field name
     * - id: contains the id
     * - model: contains the model name
     */
    openWithElement(element: HTMLElement): void {
        const content = element.parentElement?.parentElement?.getElementsByClassName('content')[0]?.innerHTML || '';
        const contentRaw = element.parentElement?.getElementsByClassName('content-raw')[0]?.textContent || '';
        const field = element.parentElement?.getElementsByClassName('field')[0]?.textContent || '';
        const id = element.parentElement?.getElementsByClassName('id')[0]?.textContent || '';
        const model = element.parentElement?.getElementsByClassName('model')[0]?.textContent || '';

        this.open({
            id: id?.trim() || '',
            model: model?.trim() || '',
            field: field?.trim() || '',
            content: content,
            contentRaw: contentRaw
        });
    }

    /**
     * Opens the modal with explicit data
     */
    open(data: FeedbackModalData): void {
        this.currentData = data;

        // Get saved sender info from localStorage
        this.senderName = localStorage.getItem('senderName') || '';
        this.senderEmail = localStorage.getItem('senderEmail') || '';

        // Reset form
        this.feedback = '';

        // Set values in modal
        this.setModalValue('modal-id', data.id);
        this.setModalValue('modal-model', data.model);
        this.setModalValue('modal-field', data.field);
        this.setModalContent('modal-content', data.content);
        this.setModalValue('modal-senderName', this.senderName);
        this.setModalValue('modal-senderEmail', this.senderEmail);

        // Open Bootstrap modal
        this.modal = new (window as any).bootstrap.Modal(document.getElementById('editModal'));
        this.modal.show();
    }

    /**
     * Closes the modal programmatically
     */
    close(): void {
        if (this.modal) {
            this.modal.hide();
        }
    }

    /**
     * Submits the feedback
     */
    submitFeedback(): void {
        if (!this.currentData) {
            return;
        }

        // Validate
        if (!this.feedback.trim() || !this.senderName.trim() || !this.senderEmail.trim()) {
            this.toastService.error('Vui lòng điền đầy đủ thông tin và góp ý!', 'Gửi góp ý thất bại');
            return;
        }

        this.toastService.info('Đang gửi góp ý...', 'Đang xử lý');

        const formData = {
            id: this.currentData.id,
            model: this.currentData.model,
            field: this.currentData.field,
            content: this.currentData.content,
            feedback: this.feedback,
            senderName: this.senderName,
            senderEmail: this.senderEmail,
        };

        const appName = this.config?.appName || 'ICD10';

        this.icdService.quickFeedback(formData, appName).subscribe(
            (res: any) => {
                if (res.status === 'success') {
                    this.toastService.success(`${res?.message}`, 'Gửi góp ý thành công');
                    this.toastService.success(`Góp ý đã được gửi thành công! Cảm ơn bạn đã đóng góp ý kiến "${this.feedback}"!`, 'Thành công');
                    this.close();

                    // Save sender info
                    localStorage.setItem('senderName', this.senderName);
                    localStorage.setItem('senderEmail', this.senderEmail);
                } else {
                    this.toastService.error(`${res?.message}`, 'Gửi góp ý thất bại');
                }
            },
            (error: any) => {
                this.toastService.error(`Lỗi khi gửi góp ý: ${error?.error?.message}`, 'Gửi góp ý thất bại');
            }
        );
    }

    private setModalValue(elementId: string, value: string): void {
        const element = document.getElementById(elementId) as HTMLInputElement;
        if (element) {
            element.value = value;
        }
    }

    private setModalContent(elementId: string, htmlContent: string): void {
        const element = document.getElementById(elementId) as HTMLDivElement;
        if (element) {
            element.innerHTML = htmlContent;
        }
    }
}
