import { Component, OnInit, ViewChild, ElementRef, Renderer2, OnDestroy } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { FormControl } from '@angular/forms';
import { IcdCodeInfo } from '../../../../shared/services/chatbot.service';
import { IcdService } from 'src/shared/services/icd.service';
import { IcfService } from 'src/shared/services/icf.service';
import { ToastrService } from 'ngx-toastr';
import { FeedbackModalComponent } from 'src/components/feedback-modal/feedback-modal.component';
import { SenseSphereOAuthService, SenseSphereBotInfo } from '../../../../shared/services/sensesphere-oauth.service';
import { Subject, Subscription } from 'rxjs';
import { takeUntil, timeout } from 'rxjs/operators';
import { environment } from '../../../../environments/environment';

// bootstrap
declare var bootstrap: any;

@Component({
    selector: 'app-chatbot',
    templateUrl: './chatbot.component.html',
    styleUrls: ['./chatbot.component.scss'],
})
export class ChatbotComponent implements OnInit, OnDestroy {
    offcanvas: any;
    isLoadingDetail: boolean = false;
    dataHtml: any;
    safeDataHtml!: SafeHtml;
    botUuid = '';
    botType = 'ICD-10';
    app = '';
    botName = '';
    @ViewChild('detailContainer') detailContainer: ElementRef<HTMLDivElement>;
    @ViewChild('feedbackModal') feedbackModal: FeedbackModalComponent;

    private destroy$ = new Subject<void>();
    private currentSubscription: Subscription | null = null;
    private offcanvasHiddenHandler: (() => void) | null = null;
    private isCurrentIcd10Tt06 = false;
    chatbotFeedbackConfig: { appName: string } = { appName: 'ICD10' };

    get isMaintenanceMode(): boolean {
        return environment.chatbot?.enabled === false;
    }

    constructor(
        private router: Router,
        private route: ActivatedRoute,
        private icdService: IcdService,
        private icfService: IcfService,
        private sanitizer: DomSanitizer,
        private toastService: ToastrService,
        private renderer: Renderer2,
        private oauthService: SenseSphereOAuthService,
    ) {}

    ngOnInit(): void {
        // Read botUuid and botType from route data
        this.route.data.subscribe(data => {
            this.botUuid = data['botUuid'] || '';
            this.botType = data['botType'] || 'ICD-10';
            this.app = data['app'] || 'ICD10';
            this.chatbotFeedbackConfig = { appName: this.app };

            if (this.botUuid) {
                this.oauthService.fetchBotInfo(this.botUuid).then(botInfo => {
                    if (botInfo) {
                        this.botName = botInfo.name;
                        document.title = `${botInfo.name} | CCMS`;
                    } else {
                        document.title = `${this.botType} Assistant | CCMS`;
                    }
                }).catch(() => {
                    document.title = `${this.botType} Assistant | CCMS`;
                });
            }
        });

        // Listen for offcanvas hidden event to reset loading state
        const offcanvasEl = document.getElementById('chatbotOffcanvasRight');
        if (offcanvasEl) {
            this.offcanvasHiddenHandler = () => {
                this.isLoadingDetail = false;
                this.cancelCurrentSubscription();
                this.botName = this.botName.replace(' | 06/2026/TT-BYT', '');
            };
            offcanvasEl.addEventListener('hidden.bs.offcanvas', this.offcanvasHiddenHandler);
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next();
        this.destroy$.complete();
        this.cancelCurrentSubscription();
        const offcanvasEl = document.getElementById('chatbotOffcanvasRight');
        if (offcanvasEl && this.offcanvasHiddenHandler) {
            offcanvasEl.removeEventListener('hidden.bs.offcanvas', this.offcanvasHiddenHandler);
        }
    }

    private cancelCurrentSubscription(): void {
        if (this.currentSubscription) {
            this.currentSubscription.unsubscribe();
            this.currentSubscription = null;
        }
        this.isLoadingDetail = false;
    }

    private intiOffCanvas() {
        if (!this.offcanvas) {
            this.offcanvas = new bootstrap.Offcanvas(document.getElementById('chatbotOffcanvasRight'));
        }
    }

    copyToClipboard(element: HTMLElement) {
        const content = element.parentElement?.getElementsByClassName('content-raw')[0]?.textContent;
        if (content) {
            navigator.clipboard.writeText(content).then(() => {
                // alert('Đã sao chép: ' + content);
                this.toastService.success('Đã sao chép: ' + content, 'Sao chép thành công');
            }).catch(() => {
                this.toastService.error('Không thể sao chép vào clipboard', 'Sao chép thất bại');
            });
        }
    }

    setClickForCopy() {
        // Tìm các icon fa-copy sau khi DOM đã được render
        setTimeout(() => {
            const copyIcons = this.detailContainer.nativeElement.querySelectorAll('.icon-copy');
            // Gắn sự kiện click cho mỗi icon
            copyIcons.forEach((icon: HTMLElement) => {
                this.renderer.listen(icon, 'click', (event) => {
                    this.copyToClipboard(icon);
                });
            });
        }, 100);
    }

    setClickForEdit() {
        // Tìm các icon fa-copy sau khi DOM đã được render
        setTimeout(() => {
            const editIcons = this.detailContainer.nativeElement.querySelectorAll('.icon-email');
            // Gắn sự kiện click cho mỗi icon
            editIcons.forEach((icon: HTMLElement) => {
                this.renderer.listen(icon, 'click', () => {
                    this.feedbackModal.openWithElement(icon);
                });
            });
        }, 100);
    }

    setClickForToggleAllIndexTerms() {
        setTimeout(() => {
            const allIndexTermsBlock = this.detailContainer.nativeElement.querySelectorAll('.all-index-terms');
            allIndexTermsBlock.forEach((block: HTMLElement) => {
                const title = block.querySelector('.card-header-index-terms') as HTMLElement;
                const terms = block.querySelector('.list-terms') as HTMLElement;
                terms?.style.setProperty('display', 'none');
                this.renderer.listen(title, 'click', () => {
                    if (terms.style.display === 'none') {
                        terms.style.display = 'block';
                    } else {
                        terms.style.display = 'none';
                    }
                });
            });
        }, 100);
    }

    setClickForJumpToDetail(app: string) {
        setTimeout(() => {
            const codes = this.detailContainer.nativeElement.querySelectorAll('a');
            codes.forEach((code: HTMLElement) => {
                const href = code.getAttribute('href');
                if (!href) return;
                const [model, id] = href.split('/');
                // TODO: need stricter check for href. Right now it's fine as all the links in the detail page are in the format of /model/id
                if (href.split("/").length === 2 && id && model) {
                    this.renderer.listen(code, 'click', (event: Event) => {
                        event.preventDefault();
                        if (this.app.startsWith('ICD10')) {
                            const targetRoute = this.isCurrentIcd10Tt06
                                ? ['icd-10-tt06', 'icd10-tt06']
                                : ['icd-10', 'icd10'];
                            this.router.navigate(targetRoute, { queryParams: { id: id, model: model } });
                        } else if (this.app.startsWith('ICD9')) {
                            this.router.navigate(['icd-9', 'icd9'], {queryParams: {id: id, model: model}})
                        } else if (this.app.startsWith('ICF')) {
                            this.router.navigate(['icf', 'icf'], {queryParams: {id: id, model: model}})
                        }
                    });
                }
            });
        }, 100);
    }

    setEventsForDetailModel(app: string) {
        this.setClickForCopy();
        this.setClickForEdit();
        this.setClickForToggleAllIndexTerms();
        this.setClickForJumpToDetail(app);
    }

    onNavigateToCode(codeInfo: IcdCodeInfo): void {
        this.cancelCurrentSubscription();

        if (!this.app) {
            this.toastService.error('Không xác định được loại dữ liệu', 'Thất bại');
            return;
        }

        this.isLoadingDetail = true;
        this.intiOffCanvas();
        this.offcanvas.show();

        const id = codeInfo.id;
        const model = codeInfo.model.toLowerCase();
        const rawPath = (codeInfo.path || '').replace(/&amp;/g, '&');
        let isIcd10Tt06Path = /^\/?icd-10-tt06\//i.test(rawPath);

        if (!isIcd10Tt06Path) {
            try {
                const parsedPath = new URL(rawPath, 'https://icd.kcb.vn').pathname;
                isIcd10Tt06Path = /^\/icd-10-tt06\//i.test(parsedPath);
            } catch {
                // Ignore invalid path and keep fallback detection result.
            }
        }

        this.isCurrentIcd10Tt06 = isIcd10Tt06Path;

        if (isIcd10Tt06Path) {
            const suffix = ' | 06/2026/TT-BYT';
            if (!this.botName.includes(suffix)) {
                this.botName = this.botName + suffix;
            }
        }

        if (this.app.startsWith('ICD10')) {
            const detailRequest$ = isIcd10Tt06Path
                ? this.icdService.getDetailModel_TT06(model, id, 'vi')
                : this.icdService.getDetailModel(model, id, 'vi');

            this.currentSubscription = detailRequest$.pipe(
                takeUntil(this.destroy$),
                timeout(30000)
            ).subscribe({
                next: (res: any) => {
                    this.isLoadingDetail = false;
                    this.dataHtml = res.data.data.html;
                    this.safeDataHtml = this.sanitizer.bypassSecurityTrustHtml(this.dataHtml);
                    this.setEventsForDetailModel(this.app);
                },
                error: (error) => {
                    this.isLoadingDetail = false;
                    const errorMessage = error?.error?.message || error?.error?.error || error?.error?.detail || error?.message || 'Có lỗi xảy ra';
                    this.toastService.error(`${errorMessage}`, 'Thất bại');
                }
            });
        } else if (this.app.startsWith('ICD9')) {
            this.currentSubscription = this.icdService.getDetailModel_ICD9(model, id, 'vi').pipe(
                takeUntil(this.destroy$),
                timeout(30000)
            ).subscribe({
                next: (res: any) => {
                    this.isLoadingDetail = false;
                    this.dataHtml = res.data.data.html;
                    this.safeDataHtml = this.sanitizer.bypassSecurityTrustHtml(this.dataHtml);
                    this.setEventsForDetailModel(this.app);
                },
                error: (error) => {
                    this.isLoadingDetail = false;
                    const errorMessage = error?.error?.message || error?.error?.error || error?.error?.detail || error?.message || 'Có lỗi xảy ra';
                    this.toastService.error(`${errorMessage}`, 'Thất bại');
                }
            });
        } else if (this.app.startsWith('ICF')) {
            this.currentSubscription = this.icfService.getDetailModel(model, id, 'vi').pipe(
                takeUntil(this.destroy$),
                timeout(30000)
            ).subscribe({
                next: (res: any) => {
                    this.isLoadingDetail = false;
                    if (res?.data?.data || res?.data) {
                        const detailData = res.data.data || res.data;
                        this.dataHtml = detailData.html;
                        this.safeDataHtml = this.sanitizer.bypassSecurityTrustHtml(this.dataHtml);
                        this.setEventsForDetailModel(this.app);
                    } else {
                        this.toastService.error('Không tải được chi tiết', 'Thất bại');
                    }
                },
                error: (error) => {
                    this.isLoadingDetail = false;
                    const errorMessage = error?.error?.message || error?.error?.error || error?.error?.detail || error?.message || 'Có lỗi xảy ra';
                    this.toastService.error(`${errorMessage}`, 'Thất bại');
                }
            });
        } else {
            this.isLoadingDetail = false;
            this.toastService.error('Không xác định được loại dữ liệu', 'Thất bại');
        }
    }
}
