import { Component } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { API_PANELS_AND_FORMS } from '../../../../../shared/common';

@Component({
  selector: 'app-loinc-panels-forms',
  templateUrl: './loinc-panels-forms.component.html',
  styleUrls: ['./loinc-panels-forms.component.scss']
})
export class LoincPanelsFormsComponent {
  panelsFormsUrl: SafeResourceUrl;
  isLoading = true;

  constructor(private sanitizer: DomSanitizer) {
    // Determine language from localStorage 'lang' key first, fallback to document/navigator
    const storedLang = localStorage.getItem('lang');
    const pageLang = (storedLang || document?.documentElement?.lang || navigator.language || 'en').toLowerCase();
    const lang = pageLang.startsWith('vi') ? 'vi' : 'en';
    const separator = API_PANELS_AND_FORMS.includes('?') ? '&' : '?';
    const panelsFormsWithLang = `${API_PANELS_AND_FORMS}${separator}lang=${lang}`;
    this.panelsFormsUrl = this.sanitizer.bypassSecurityTrustResourceUrl(panelsFormsWithLang);
  }

  onIframeLoad() {
    // Đảm bảo loading hiển thị ít nhất 500ms để người dùng thấy
    setTimeout(() => {
      this.isLoading = false;
    }, 100);
  }
}
