import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { Router } from '@angular/router';
import { ChatbotService } from '../../shared/services/chatbot.service';
import { CHATBOT_CONFIG } from '../../shared/constants/chatbot.constants';

// Full-page chatbot routes, used when the current page has no mini chatbot
const CHATBOT_ROUTE_BY_BOT: Record<string, string> = {
    [CHATBOT_CONFIG.icd10BotUuid]: '/chatbot/icd-10',
    [CHATBOT_CONFIG.icd9BotUuid]: '/chatbot/icd-9',
    [CHATBOT_CONFIG.icfBotUuid]: '/chatbot/icf',
};

/**
 * Offers to forward a manual search keyword to the AI assistant.
 * - 'empty': full empty state, shown in place of the results when nothing matches
 * - 'inline': one-line hint shown under results that may not be relevant
 */
@Component({
    selector: 'app-ask-ai-fallback',
    templateUrl: './ask-ai-fallback.component.html',
    styleUrls: ['./ask-ai-fallback.component.scss'],
})
export class AskAiFallbackComponent implements OnChanges {
    @Input() query = '';
    @Input() botUuid = CHATBOT_CONFIG.icd10BotUuid;
    // Classification name used in the question, e.g. 'ICD-10', 'ICD-9', 'ICF'
    @Input() botType = 'ICD-10';
    @Input() variant: 'empty' | 'inline' = 'empty';
    // Emitted after the question has been handed to the assistant (e.g. to close a results dropdown)
    @Output() asked = new EventEmitter<void>();

    sent = false;

    constructor(private chatbotService: ChatbotService, private router: Router) {}

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['query'] || changes['botUuid']) {
            this.sent = false;
        }
    }

    get trimmedQuery(): string {
        return (this.query || '').trim();
    }

    onAsk(event: Event): void {
        // Keep the click inside dropdowns whose window listeners would treat it as an outside click
        event.stopPropagation();
        if (this.sent || !this.trimmedQuery) {
            return;
        }
        this.sent = true;

        const question = this.variant === 'inline'
            ? `Tôi tìm "${this.trimmedQuery}" trong ${this.botType} nhưng chưa thấy mã phù hợp trong kết quả. Hãy giúp tôi tìm mã ${this.botType} phù hợp.`
            : `Tôi tìm "${this.trimmedQuery}" trong ${this.botType} nhưng không có kết quả. Hãy giúp tôi tìm mã ${this.botType} phù hợp.`;
        const opened = this.chatbotService.askAssistant(this.botUuid, question);
        if (!opened) {
            this.router.navigateByUrl(CHATBOT_ROUTE_BY_BOT[this.botUuid] || '/chatbot/icd-10');
        }
        this.asked.emit();
    }
}
