import { Component, Input, Output, EventEmitter, AfterViewInit, OnDestroy, OnChanges, SimpleChanges } from '@angular/core';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { ChatbotService, IcdCodeInfo } from '../../shared/services/chatbot.service';

@Component({
    selector: 'app-chatbot-mini',
    templateUrl: './chatbot-mini.component.html',
    styleUrls: ['./chatbot-mini.component.scss'],
})
export class ChatbotMiniComponent implements AfterViewInit, OnDestroy, OnChanges {
    @Input() showChatbot = false;
    @Input() botUuid = '';
    @Input() botType = 'ICD-10';
    @Output() closeChatbot = new EventEmitter<void>();
    @Output() openChatbot = new EventEmitter<void>();

    private vhResizeHandler?: () => void;
    private registeredBotUuid = '';
    private openRequestSub: Subscription;

    constructor(private router: Router, private chatbotService: ChatbotService) {
        // Open when a manual search with no results forwards a question to this bot
        this.openRequestSub = this.chatbotService.openRequest$.subscribe(botUuid => {
            if (botUuid === this.botUuid && !this.showChatbot) {
                this.openChatbot.emit();
            }
        });
    }

    ngAfterViewInit(): void {
        this.setVH();
        this.vhResizeHandler = () => this.setVH();
        window.addEventListener('resize', this.vhResizeHandler);
    }

    ngOnDestroy(): void {
        if (this.vhResizeHandler) {
            window.removeEventListener('resize', this.vhResizeHandler);
        }
        document.body.classList.remove('chatbot-mini-open');
        this.openRequestSub.unsubscribe();
        if (this.registeredBotUuid) {
            this.chatbotService.unregisterHost(this.registeredBotUuid);
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['botUuid'] && this.botUuid !== this.registeredBotUuid) {
            if (this.registeredBotUuid) {
                this.chatbotService.unregisterHost(this.registeredBotUuid);
            }
            this.registeredBotUuid = this.botUuid;
            if (this.botUuid) {
                this.chatbotService.registerHost(this.botUuid);
            }
        }
        if (changes['showChatbot']) {
            if (this.showChatbot) {
                document.body.classList.add('chatbot-mini-open');
            } else {
                document.body.classList.remove('chatbot-mini-open');
            }
        }
    }

    private setVH(): void {
        const vh = window.innerHeight * 0.01;
        document.documentElement.style.setProperty('--vh', `${vh}px`);
    }

    onClose(): void {
        this.closeChatbot.emit();
    }

    onNavigateToCode(codeInfo: IcdCodeInfo): void {
        const path = (codeInfo.path || '').replace(/&amp;/g, '&');
        try {
            const url = /^https?:\/\//i.test(path) ? new URL(path) : null;
            this.router.navigateByUrl(url ? url.pathname + url.search : path);
        } catch {
            return;
        }
        this.onClose();
    }
}
